let ready=false,lastMaintenance=0,lastLeaderboardRepair=0;async function ensure(){if(ready)return;for(const sql of ROOM_SCHEMA)await db().prepare(sql).run();ready=true}
export async function digest(v:string){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v));return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('')}
export const token=()=>crypto.randomUUID()+crypto.randomUUID();
export function code(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';const bytes=crypto.getRandomValues(new Uint8Array(6));return [...bytes].map(x=>chars[x%chars.length]).join('')}
export async function cleanup(){await ensure();const now=Date.now();await db().prepare('DELETE FROM room_members WHERE room_code IN (SELECT code FROM rooms WHERE expires_at < ?)').bind(now).run();await db().prepare('DELETE FROM rooms WHERE expires_at < ?').bind(now).run();await db().prepare('DELETE FROM room_actions WHERE created_at < ?').bind(now-7*86400000).run();await db().prepare('DELETE FROM request_limits WHERE window_start < ?').bind(now-10*60000).run();lastMaintenance=now}
export async function rateLimit(key:string,max=40,windowMs=60000){await ensure();const now=Date.now(),start=now-windowMs;if(now-lastMaintenance>5*60000){await db().prepare('DELETE FROM request_limits WHERE window_start < ?').bind(now-10*60000).run();await db().prepare('DELETE FROM room_actions WHERE created_at < ?').bind(now-7*86400000).run();lastMaintenance=now}const row=await db().prepare(`INSERT INTO request_limits(limit_key,window_start,request_count) VALUES(?,?,1) ON CONFLICT(limit_key) DO UPDATE SET window_start=CASE WHEN window_start<? THEN excluded.window_start ELSE window_start END,request_count=CASE WHEN window_start<? THEN 1 ELSE request_count+1 END RETURNING request_count`).bind(key,now,start,start).first<{request_count:number}>();if((row?.request_count||1)>max)throw new RoomError('RATE_LIMITED','Çok fazla istek gönderildi. Lütfen kısa süre sonra tekrar deneyin.',429)}
