export async function createRoom(name:string,settings:RoomSettings){await cleanup();for(let attempt=0;attempt<5;attempt++){const roomCode=code(),hostToken=token(),memberToken=token(),memberId=crypto.randomUUID(),now=Date.now();const state:RoomState={code:roomCode,status:'lobby',settings:normalizedSettings(settings),members:[{id:memberId,name,role:'manager',approved:true,leaderboardOptIn:false}],createdAt:now};try{await db().batch([db().prepare('INSERT INTO rooms VALUES (?,?,?,?,?,?)').bind(roomCode,await digest(hostToken),JSON.stringify(state),0,now,now+7*86400000),db().prepare('INSERT INTO room_members VALUES (?,?,?,?,?,?,?)').bind(roomCode,memberId,await digest(memberToken),name,'manager',1,now)]);return{code:roomCode,hostToken,memberToken,memberId}}catch(error){if(attempt===4)throw error}}throw new RoomError('ROOM_CREATE_FAILED','Oda oluşturulamadı. Lütfen tekrar deneyin.',503)}
export async function joinRoom(roomCode:string,name:string,role:'manager'|'spectator'){await ensure();for(let attempt=0;attempt<5;attempt++){const row=await db().prepare('SELECT state_json,revision FROM rooms WHERE code=? AND expires_at>?').bind(roomCode,Date.now()).first<{state_json:string;revision:number}>();if(!row)throw new RoomError('ROOM_NOT_FOUND','Oda bulunamadı',404);const state=JSON.parse(row.state_json) as RoomState;if(state.status!=='lobby')throw new RoomError('GAME_STARTED','Oyun başladı',409);if(state.members.some(m=>m.name.toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr')))throw new RoomError('NAME_TAKEN','Bu isim kullanılıyor',409);if(role==='manager'&&state.members.filter(m=>m.role==='manager').length>=8)throw new RoomError('ROOM_FULL','Menajer kontenjanı dolu',409);if(state.members.length>=24)throw new RoomError('ROOM_FULL','Oda katılımcı sınırına ulaştı',409);const memberId=crypto.randomUUID(),memberToken=token(),member={id:memberId,name,role,approved:false,leaderboardOptIn:false};await db().prepare('INSERT INTO room_members VALUES (?,?,?,?,?,?,?)').bind(roomCode,memberId,await digest(memberToken),name,role,0,Date.now()).run();state.members.push(member);try{const updated=await db().prepare('UPDATE rooms SET state_json=?,revision=revision+1 WHERE code=? AND revision=?').bind(JSON.stringify(state),roomCode,row.revision).run();if(updated.meta.changes)return{code:roomCode,memberToken,memberId}}catch(error){await db().prepare('DELETE FROM room_members WHERE room_code=? AND member_id=?').bind(roomCode,memberId).run();throw error}await db().prepare('DELETE FROM room_members WHERE room_code=? AND member_id=?').bind(roomCode,memberId).run()}throw new RoomError('REVISION_CONFLICT','Oda aynı anda güncellendi. Tekrar deneyin.',409)}
export async function auth(roomCode:string,plain:string){await ensure();const hash=await digest(plain);const room=await db().prepare('SELECT state_json,revision,host_token_hash FROM rooms WHERE code=? AND expires_at>?').bind(roomCode,Date.now()).first<{state_json:string;revision:number;host_token_hash:string}>();if(!room)throw new RoomError('ROOM_EXPIRED','Oda bulunamadı veya süresi doldu',410);const state=JSON.parse(room.state_json) as RoomState;if(room.host_token_hash===hash){const projected=await db().prepare("SELECT member_id,name,role,approved FROM room_members WHERE room_code=? AND role='manager' ORDER BY rowid LIMIT 1").bind(roomCode).first<{member_id:string;name:string;role:'manager';approved:number}>(),authoritative=state.members.find(item=>item.id===projected?.member_id);const member=projected&&authoritative?{...projected,name:authoritative.name,role:authoritative.role,approved:Number(authoritative.approved)}:projected;return{room,state,isHost:true,member}}const projected=await db().prepare('SELECT member_id,name,role,approved,last_seen FROM room_members WHERE room_code=? AND token_hash=?').bind(roomCode,hash).first<{member_id:string;name:string;role:'manager'|'spectator';approved:number;last_seen:number}>();const authoritative=state.members.find(item=>item.id===projected?.member_id);if(!projected||!authoritative)throw new RoomError('AUTH_INVALID','Bağlantı yetkisi geçersiz',401);const member={...projected,name:authoritative.name,role:authoritative.role,approved:Number(authoritative.approved)};if(Date.now()-projected.last_seen>30000)await db().prepare('UPDATE room_members SET last_seen=? WHERE room_code=? AND member_id=?').bind(Date.now(),roomCode,projected.member_id).run();return{room,state,isHost:false,member}}
function rememberCurrentLots(state:RoomState){state.recentLotIds=[...new Set([...(state.recentLotIds||[]),...(state.game?.pool||[]).map(lot=>lot.id)])].slice(-600)}
function recentLotIds(state:RoomState){return new Set(state.recentLotIds||[])}
export function estimateAuctionDuration(settings:RoomSettings,managerCount:number){const groups=11+(settings.includeBench?4:0)+1,lots=groups*(Math.max(2,managerCount)+1),secondsPerLot=settings.auctionMode==='manual'?12:(settings.timerSeconds||20)+4;return{lots,minutes:Math.max(1,Math.ceil(lots*secondsPerLot/60)),fastRecommended:lots>=80}}
export function standardEligibility(state:RoomState){const humanCount=state.members.filter(member=>member.approved&&member.role==='manager'&&!member.isBot).length,aiManagerCount=state.members.filter(member=>member.approved&&member.role==='manager'&&member.isBot).length,scenarioId=state.settings.scenarioId||'classic',poolMode=state.settings.poolMode||'generated',evaluation=standardLeaderboardEligibility({era:state.settings.era,selectedTiers:state.settings.selectedTiers,benchEnabled:Boolean(state.settings.includeBench),mode:'online',auctionMode:state.settings.auctionMode||'live',scenarioId,customPool:poolMode==='custom',automationUsed:Boolean(state.autoCompleted),humanManagerCount:humanCount,aiManagerCount,timerSeconds:state.settings.timerSeconds||20,bidIncrement:state.settings.bidIncrement||5,datasetVersion:datasetManifest.datasetVersion,scoreVersion:datasetManifest.scoreVersion});return{standardEligible:evaluation.eligible,autoCompleted:Boolean(state.autoCompleted),humanCount,aiManagerCount,scenarioId,poolMode,includeBench:Boolean(state.settings.includeBench),era:state.settings.era,selectedTiers:[...state.settings.selectedTiers],timerSeconds:state.settings.timerSeconds||20,bidIncrement:state.settings.bidIncrement||5,datasetVersion:datasetManifest.datasetVersion,scoreVersion:datasetManifest.scoreVersion,rulesFingerprint:evaluation.fingerprint}}
export function publicStateView(state:RoomState){const view=structuredClone(state),sourceGame=state.game;if(!view.game||!sourceGame)return view;const current=sourceGame.pool[sourceGame.index],key=current?auctionGroupKey(current):'',groupOrdinal=current?sourceGame.pool.slice(0,sourceGame.index+1).filter(lot=>auctionGroupKey(lot)===key).length:0;view.game.publicMeta={currentIsBonus:Boolean(current&&isBonusPlayerLot(sourceGame.pool,sourceGame.index,sourceGame.managers.length)),currentPassIsSafe:Boolean(current&&auctionPassIsSafe(sourceGame.pool,sourceGame.index,sourceGame.managers)),groupOrdinal,totalLots:sourceGame.pool.length,canUndo:Boolean(sourceGame.undo)};view.game.undo=undefined;view.game.undoStatus=undefined;const {pool,index}=view.game;view.game.pool=pool.map((lot,lotIndex)=>{if(lotIndex<index)return lot;if(lotIndex===index){if(view.settings.revealRatings)return lot;const safe:Partial<AuctionLot>={...lot};delete safe.rating;return safe as AuctionLot}return{id:`hidden-${lotIndex}`,name:'Gizli lot',slot:'ST',role:'Sıradaki lot',rating:0,price:0,nation:'',club:''} satisfies Footballer});return view}
