async function backfillLeaderboard(){const rows=await db().prepare("SELECT state_json FROM rooms WHERE json_extract(state_json,'$.status')='results' ORDER BY created_at DESC LIMIT 200").all<{state_json:string}>();for(const row of rows.results||[])try{await persistLeaderboard(JSON.parse(row.state_json) as RoomState)}catch{}}
async function removeMemberLeaderboard(roomCode:string,memberId:string){const entries=await db().prepare('SELECT id FROM leaderboard_entries WHERE room_code=? AND member_id=?').bind(roomCode,memberId).all<{id:string}>(),now=Date.now(),statements=(entries.results||[]).map(entry=>db().prepare('INSERT OR REPLACE INTO leaderboard_deletions(entry_id,deleted_at) VALUES(?,?)').bind(entry.id,now));statements.push(db().prepare('DELETE FROM leaderboard_entries WHERE room_code=? AND member_id=?').bind(roomCode,memberId));await db().batch(statements)}
