export async function deleteLeaderboardEntry(roomCode:string,plain:string,entryId:string){await ensure();const tokenHash=await digest(plain),entry=await db().prepare('SELECT member_id,delete_token_hash FROM leaderboard_entries WHERE id=? AND room_code=?').bind(entryId,roomCode).first<{member_id:string|null;delete_token_hash:string|null}>();if(!entry)throw new RoomError('ENTRY_NOT_FOUND','Başarı kaydı bulunamadı',404);let ctx:Awaited<ReturnType<typeof auth>>|undefined;if(entry.delete_token_hash!==tokenHash){ctx=await auth(roomCode,plain);if(!ctx.isHost&&entry.member_id!==ctx.member?.member_id)throw new RoomError('FORBIDDEN','Bu başarı kaydını silemezsiniz',403)}else try{ctx=await auth(roomCode,plain)}catch{}if(ctx){const member=ctx.state.members.find(item=>item.id===entry.member_id);if(member){member.leaderboardOptIn=false;try{await saveState(roomCode,ctx.state,ctx.room.revision)}catch{}}}await db().batch([db().prepare('INSERT OR REPLACE INTO leaderboard_deletions(entry_id,deleted_at) VALUES(?,?)').bind(entryId,Date.now()),db().prepare('DELETE FROM leaderboard_entries WHERE id=? AND room_code=?').bind(entryId,roomCode)]);return{deleted:true}}
